# Unit 8 · Sports day!  –  chủ điểm do cô Thảo cung cấp: present continuous (future); going to; tag questions; present perfect + already
# Quy tắc: chỗ trống của câu điền từ chỉ hỏi NGỮ PHÁP (trợ động từ, giới từ, từ nối, dạng động từ), chỉ có một đáp án hợp lý.
from ugen import *

L1 = lesson('l1', 'mint', '📅', 'Present continuous (future)', 'Kế hoạch đã sắp xếp: am / is / are + V-ing',
 'Mai có trận đấu! Dùng am / is / are + V-ing để nói kế hoạch đã sắp xếp nhé.',
 [when('🧭 Khi nào dùng?', [
    ('📅', '**am / is / are + V-ing + thời gian tương lai** = kế hoạch đã sắp xếp.', 'We are playing volleyball on Saturday.', 'Thứ Bảy chúng mình chơi bóng chuyền.'),
    ('⏰', 'Có từ chỉ tương lai: **tomorrow, on Saturday, next week**.', 'Our team is playing a match tomorrow.', 'Ngày mai đội mình thi đấu.'),
    ('🔎', '**Không** có từ tương lai → thường là việc **đang diễn ra** lúc này.', 'They are playing volleyball now.', 'Bây giờ họ đang chơi bóng chuyền.')]),
  compare('🗂 So sánh: đang làm hay kế hoạch?', [
    CI('am / is / are + V-ing (now)', 'sub', 'đang làm', 'Việc **đang diễn ra** ngay lúc nói (now, at the moment).', [('She is playing golf now.', 'Bây giờ cô ấy đang chơi gôn.')], V('golf')),
    CI('am / is / are + V-ing + future time', 'pink', 'kế hoạch', 'Việc **đã sắp xếp** cho tương lai (tomorrow, on Saturday).', [('She is playing golf on Saturday.', 'Thứ Bảy cô ấy sẽ chơi gôn.')], EM('📅'))]),
  pattern('1️⃣ Kế hoạch: am / is / are + V-ing + time', 'mint', [('subject', 'sub', 'I, she, we'), ('am / is / are', 'aux', ''), ('V-ing', 'v', 'playing, running'), ('thing', 'obj', 'a match'), ('future time', 'pre', 'tomorrow')], [
    ('{We|sub} {are|aux} {playing|v} {volleyball|obj} {on Saturday.|pre}', 'Thứ Bảy chúng mình chơi bóng chuyền.', V('volleyball')),
    ('{Our team|sub} {is|aux} {playing|v} {a match|obj} {tomorrow.|pre}', 'Ngày mai đội mình thi đấu.', V('match')),
    ('{I|sub} {am|aux} {running|v} {in the race|obj} {next week.|pre}', 'Tuần sau mình chạy đua.', V('race'))]),
  pattern("2️⃣ Không có kế hoạch: am not / isn't / aren't + V-ing", 'rose', [('subject', 'sub', 'I, he, they'), ("am not / isn't / aren't", 'pink', 'không'), ('V-ing', 'v', 'playing'), ('future time', 'pre', 'on Sunday')], [
    ("{We|sub} {aren't|pink} {playing|v} {golf|obj} {on Sunday.|pre}", 'Chủ nhật chúng mình không chơi gôn.', V('golf')),
    ("{He|sub} {isn't|pink} {running|v} {in the race|obj} {tomorrow.|pre}", 'Ngày mai cậu ấy không chạy đua.', V('race')),
    ("{I|sub} {am not|pink} {playing|v} {today.|pre}", 'Hôm nay mình không thi đấu. (đầu gối đau)', V('knee'))]),
  dialog('❓ Hỏi và trả lời', '{Are|aux} {you|sub} {playing|v} {…|obj} {on Saturday?|pre}', [
    ('{Are|aux} {you|sub} {playing|v} {volleyball|obj} {on Saturday?|pre}', '{Yes,|sub} {I am.|aux}', 'Thứ Bảy bạn chơi bóng chuyền à?', 'Ừ, mình chơi.', V('volleyball')),
    ('{Is|aux} {she|sub} {playing|v} {golf|obj} {tomorrow?|pre}', "{No,|sub} {she isn't.|pink}", 'Ngày mai cô ấy chơi gôn à?', 'Không, cô ấy không chơi.', V('golf'))]),
  tip('💡 Mẹo: **am / is / are + V-ing** + từ chỉ tương lai (tomorrow, on Saturday…) = kế hoạch. Không có từ chỉ tương lai → việc đang xảy ra.'),
  mistakes([('We playing volleyball on Saturday.', 'We are playing volleyball on Saturday.', 'Thiếu are.'), ('She are playing golf tomorrow.', 'She is playing golf tomorrow.', 'She → is.'),
            ('I am play a match on Friday.', 'I am playing a match on Friday.', 'am + V-ing.'), ('Are you play tomorrow?', 'Are you playing tomorrow?', 'Are + chủ ngữ + V-ing?')]),
  acts('a1')],
 [Mc('We ___ volleyball on Saturday.', 'are playing', 'is playing', 'playing', 'Kế hoạch: We are playing.', V('volleyball')),
  Mc('Our team ___ a match tomorrow.', 'is playing', 'are playing', 'playing', 'Our team (một đội) → is playing.', V('match')),
  Mc('I ___ in the race next week.', 'am running', 'is running', 'running', 'I → am running.', V('race')),
  Mc('Look! They ___ volleyball now.', 'are playing', 'is playing', 'plays', 'now → đang chơi: are playing.', V('volleyball')),
  Mc('She ___ golf on Sunday.', 'is playing', 'are playing', 'playing', 'She → is playing.', V('golf')),
  Mc('___ you playing in the match tomorrow?', 'Are', 'Is', 'Do', 'You → Are you playing…?', V('match')),
  Mc('My dad ___ to sports day on Friday.', 'is coming', 'are coming', 'coming', 'My dad → is coming.'),
  Mc("We ___ playing tomorrow. The match is cancelled.", "aren't", "isn't", "don't", 'We → aren\'t playing.'),
  Mc('The winner ___ a prize on Saturday.', 'is getting', 'are getting', 'getting', 'The winner → is getting.', V('prize')),
  Mc('They ___ for the competition now.', 'are practising', 'is practising', 'practises', 'now → đang luyện: are practising.', V('competition')),
  Fl('We are ___ volleyball on Saturday. (play)', 'playing', ['playing', 'play', 'plays'], 'are + V-ing → playing.', V('volleyball')),
  Fl('I ___ meeting my team tomorrow.', 'am', ['am', 'is', 'are'], 'I → am meeting.', V('team')),
  Fl('Our team ___ playing a match on Friday.', 'is', ['is', 'are', 'am'], 'Our team → is playing.', V('match')),
  Fl('___ you running in the race on Sunday?', 'Are', ['Are', 'Is', 'Do'], 'You → Are you running…?', V('race')),
  Fl('She is ___ golf next week. (play)', 'playing', ['playing', 'play', 'plays'], 'is + V-ing → playing.', V('golf')),
  Fl("They aren't ___ on Saturday. (play)", 'playing', ['playing', 'play', 'plays'], "aren't + V-ing → playing."),
  Fl('My dad ___ coming to the match tomorrow.', 'is', ['is', 'are', 'am'], 'My dad → is coming.'),
  Fl('We ___ going to sports day on Friday.', 'are', ['are', 'is', 'am'], 'We → are going.'),
  Fl('I ___ not playing tomorrow. My knee is sore.', 'am', ['am', 'is', 'are'], 'I → am not playing.', V('knee')),
  Fl('He is ___ his friend on Saturday. (meet)', 'meeting', ['meeting', 'meet', 'meets'], 'is + V-ing → meeting.')],
 [Dlg(['Mum: What are you doing on Saturday?'], 'Tom: I ___ in a volleyball match.', 'am playing', 'is playing', 'playing', 'Kế hoạch: I am playing.', V('volleyball')),
  Dlg(['Girl: Is your sister running in the race?'], "Boy: No, she ___ running. She is sore.", "isn't", "aren't", "doesn't", "No, she isn't running.", V('race')),
  Dlg(['Teacher: Are you coming to sports day?'], 'Pupil: Yes, we ___.', 'are', 'is', 'do', 'Trả lời Yes, we are.'),
  Clz(['Tomorrow is sports day.', 'Our team has a big match.'], 'We ___ at nine o\'clock.', 'are playing', 'is playing', 'playing', 'We → are playing.', V('team')),
  Clz(['Look at the track.', 'The runners are ready.'], 'They ___ in the race now.', 'are running', 'is running', 'running', 'now → đang chạy: are running.', V('race')),
  Clz(['Ben is not well.', 'He hurt his knee.'], "He ___ playing on Saturday.", "isn't", "aren't", "doesn't", "He isn't playing.", V('knee'))])

L2 = lesson('l2', 'sky', '🎯', 'going to', 'Dự định và điều sắp xảy ra',
 'Hôm nay em định làm gì? Dùng am / is / are going to nhé!',
 [when('🧭 Khi nào dùng?', [
    ('🎯', '**am / is / are going to + verb** = **dự định** sắp làm.', 'I am going to play volleyball.', 'Mình định chơi bóng chuyền.'),
    ('👀', 'Cũng dùng khi **thấy dấu hiệu** điều sắp xảy ra.', 'Look! He is going to fall over!', 'Nhìn kìa! Cậu ấy sắp ngã!'),
    ('❓', 'Hỏi: **Are you going to …?** Trả lời: **Yes, I am. / No, I\'m not.**', 'Are you going to win?', 'Bạn định thắng à?')]),
  three('🗂 Ba kiểu câu', [('✅', 'Câu có', 'mint', 'I [[am going to]] win.', 'Mình định thắng.'), ('❌', 'Câu không', 'rose', "I [[am not going to]] win.", 'Mình không định thắng.'), ('❓', 'Câu hỏi', 'sky', '[[Are]] you [[going to]] win?', 'Bạn định thắng à?')]),
  pattern('1️⃣ Dự định: am / is / are going to + verb', 'sky', [('subject', 'sub', 'I, he, we'), ('am / is / are going to', 'aux', 'định'), ('verb', 'v', 'win, play'), ('thing', 'obj', 'the race')], [
    ('{I|sub} {am going to|aux} {win|v} {the race.|obj}', 'Mình định thắng cuộc đua.', V('winner')),
    ('{She|sub} {is going to|aux} {play|v} {golf.|obj}', 'Cô ấy định chơi gôn.', V('golf')),
    ('{We|sub} {are going to|aux} {score|v} {a goal.|obj}', 'Chúng mình định ghi bàn.', V('goal'))]),
  pattern("2️⃣ Không định: am not / isn't / aren't going to", 'rose', [('subject', 'sub', 'I, he, they'), ("'m not / isn't / aren't going to", 'pink', 'không định'), ('verb', 'v', 'play'), ('thing', 'obj', 'golf')], [
    ("{I|sub} {am not going to|pink} {play|v} {golf.|obj}", 'Mình không định chơi gôn.', V('golf')),
    ("{He|sub} {isn't going to|pink} {run|v} {in the race.|obj}", 'Cậu ấy không định chạy đua.', V('race')),
    ("{They|sub} {aren't going to|pink} {lose|v} {the match.|obj}", 'Họ không định thua trận.', V('match'))]),
  dialog('❓ Hỏi và trả lời', '{Are|aux} {you|sub} {going to|pink} {+ verb?|v}', [
    ('{Are|aux} {you|sub} {going to|pink} {win|v} {the race?|obj}', '{Yes,|sub} {I am.|aux}', 'Bạn định thắng cuộc đua à?', 'Ừ, mình định thắng.', V('race')),
    ('{Is|aux} {he|sub} {going to|pink} {play|v} {golf?|obj}', "{No,|sub} {he isn't.|pink}", 'Cậu ấy định chơi gôn à?', 'Không, cậu ấy không định chơi.', V('golf'))]),
  tip('💡 Mẹo: **am / is / are + going to + động từ nguyên mẫu**. Chọn am / is / are theo chủ ngữ: I → am · he / she / it → is · we / you / they → are.'),
  mistakes([('I going to win the race.', 'I am going to win the race.', 'Thiếu am.'), ('She is going to plays golf.', 'She is going to play golf.', 'Sau going to dùng động từ nguyên mẫu.'),
            ('They is going to score.', 'They are going to score.', 'They → are.'), ('Are you going win?', 'Are you going to win?', 'Thiếu to.')]),
  acts('a2')],
 [Mc('I ___ going to win the race.', 'am', 'is', 'are', 'I → am going to.', V('race')),
  Mc('She ___ going to play golf.', 'is', 'am', 'are', 'She → is going to.', V('golf')),
  Mc('We are going to ___ a goal.', 'score', 'scores', 'scoring', 'Sau going to dùng động từ nguyên mẫu.', V('goal')),
  Mc('They ___ going to lose the match.', 'are', 'is', 'am', 'They → are going to.', V('match')),
  Mc('___ you going to play volleyball?', 'Are', 'Is', 'Am', 'You → Are you going to…?', V('volleyball')),
  Mc('Look! He ___ going to fall over!', 'is', 'are', 'am', 'He → is going to. (thấy dấu hiệu)', V('fall-over')),
  Mc("I am not going to ___ golf.", 'play', 'plays', 'playing', 'Sau going to dùng động từ nguyên mẫu.', V('golf')),
  Mc("A: Is she going to win? B: No, she ___.", "isn't", "aren't", "doesn't", "Trả lời No, she isn't.", V('winner')),
  Mc('Our team ___ going to win the prize.', 'is', 'are', 'am', 'Our team → is going to.', V('prize')),
  Mc("They aren't going ___ run in the race.", 'to', 'for', 'at', 'going to + verb.', V('race')),
  Fl('I ___ going to play volleyball.', 'am', ['am', 'is', 'are'], 'I → am going to.', V('volleyball')),
  Fl('She is ___ to win the race.', 'going', ['going', 'go', 'goes'], 'is going to + verb.', V('race')),
  Fl('They ___ going to score a goal.', 'are', ['are', 'is', 'am'], 'They → are going to.', V('goal')),
  Fl('He is going to ___ the match. (win)', 'win', ['win', 'wins', 'winning'], 'Sau going to dùng động từ nguyên mẫu.', V('winner')),
  Fl('We ___ not going to lose.', 'are', ['are', 'is', 'am'], 'We → are not going to.'),
  Fl('___ she going to play golf?', 'Is', ['Is', 'Are', 'Am'], 'She → Is she going to…?', V('golf')),
  Fl('Are you going ___ run in the race?', 'to', ['to', 'for', 'at'], 'are going to + verb.', V('race')),
  Fl('A: Is he going to win? B: Yes, he ___.', 'is', ['is', 'are', 'does'], 'Trả lời Yes, he is.', V('winner')),
  Fl("I'm going to ___ a prize. (get)", 'get', ['get', 'gets', 'getting'], 'Sau going to dùng động từ nguyên mẫu.', V('prize')),
  Fl('Look! The ball ___ going to hit the goal!', 'is', ['is', 'are', 'am'], 'The ball → is going to.', V('goal'))],
 [Dlg(['Mum: What are you going to do today?'], 'Tom: I ___ going to play volleyball.', 'am', 'is', 'are', 'I → am going to.', V('volleyball')),
  Dlg(['Girl: Is your team going to win?'], 'Boy: Yes, it ___.', 'is', 'are', 'does', 'Trả lời Yes, it is.', V('team')),
  Dlg(['Teacher: Are you going to run?'], "Pupil: No, I'm ___.", 'not', "isn't", "don't", "No, I'm not.", V('race')),
  Clz(['Amy is at the start line.', 'She is very fast.'], 'She ___ going to win the race.', 'is', 'are', 'am', 'She → is going to.', V('race')),
  Clz(['The ball is near the goal.', 'The player kicks it.'], 'He is ___ to score!', 'going', 'go', 'goes', 'is going to score.', V('goal')),
  Clz(['Ben hurt his knee.', 'The doctor says rest.'], "He ___ going to play today.", "isn't", "aren't", "doesn't", "He isn't going to play.", V('knee'))])

L3 = lesson('l3', 'peach', '❓', 'Tag questions', 'Câu hỏi đuôi: …, isn\'t it?',
 'Em nghĩ điều đó đúng và muốn hỏi lại để chắc chắn? Dùng câu hỏi đuôi (tag question) nhé!',
 [when('🧭 Khi nào dùng?', [
    ('❓', '**Tag question** = đuôi hỏi thêm vào cuối câu để **xác nhận**.', 'You like volleyball, don\'t you?', 'Bạn thích bóng chuyền, đúng không?'),
    ('⚖️', 'Câu **khẳng định** → đuôi **phủ định**.', 'She is fast, isn\'t she?', 'Cô ấy chạy nhanh, đúng không?'),
    ('⚖️', 'Câu **phủ định** → đuôi **khẳng định**.', "She isn't sore, is she?", 'Cô ấy không đau, đúng không?')]),
  compare('🗂 So sánh: ghép khẳng định và phủ định', [
    CI('Câu (+) , đuôi (−)', 'sub', 'khẳng định + đuôi phủ định', 'Câu khẳng định thì đuôi có **n\'t**.', [("You are in the team, aren't you?", 'Bạn trong đội, đúng không?'), ("He plays golf, doesn't he?", 'Cậu ấy chơi gôn, đúng không?')], V('team')),
    CI('Câu (−) , đuôi (+)', 'pink', 'phủ định + đuôi khẳng định', 'Câu phủ định thì đuôi **không có n\'t**.', [("You aren't sore, are you?", 'Bạn không đau, đúng không?'), ("He doesn't play golf, does he?", 'Cậu ấy không chơi gôn, đúng không?')], V('sore'))]),
  table('🗂 Đuôi lấy theo trợ động từ của câu', ['Trợ động từ trong câu', 'Đuôi', 'Ví dụ'], [
    ['is / are', "isn't / aren't", 'You are → aren\'t you?'], ['can', "can't", 'He can run → can\'t he?'], ['động từ thường (hiện tại)', "don't / doesn't", 'She plays → doesn\'t she?'],
    ['động từ quá khứ', "didn't", 'They won → didn\'t they?'], ['will', "won't", 'We will win → won\'t we?']], ['sky', 'rose', 'mint']),
  pattern('1️⃣ Câu khẳng định + đuôi phủ định', 'peach', [('statement (+)', 'sub', 'You like volleyball'), ("tag (−)", 'pink', "don't you?")], [
    ("{You like volleyball,|sub} {don't you?|pink}", 'Bạn thích bóng chuyền, đúng không?', V('volleyball')),
    ("{She is a winner,|sub} {isn't she?|pink}", 'Cô ấy là người thắng, đúng không?', V('winner')),
    ("{They won the match,|sub} {didn't they?|pink}", 'Họ thắng trận, đúng không?', V('match'))]),
  pattern("2️⃣ Câu phủ định + đuôi khẳng định", 'rose', [("statement (−)", 'sub', "You don't like golf"), ('tag (+)', 'aux', 'do you?')], [
    ("{You don't like golf,|sub} {do you?|aux}", 'Bạn không thích gôn, đúng không?', V('golf')),
    ("{She isn't sore,|sub} {is she?|aux}", 'Cô ấy không đau, đúng không?', V('sore')),
    ("{They didn't score,|sub} {did they?|aux}", 'Họ không ghi bàn, đúng không?', V('score'))]),
  dialog('❓ Hỏi và trả lời', '{Statement,|sub} {tag?|pink}', [
    ("{You are in the team,|sub} {aren't you?|pink}", '{Yes,|sub} {I am.|aux}', 'Bạn trong đội, đúng không?', 'Ừ, mình trong đội.', V('team')),
    ("{He doesn't like golf,|sub} {does he?|aux}", "{No,|sub} {he doesn't.|pink}", 'Cậu ấy không thích gôn, đúng không?', 'Ừ, cậu ấy không thích.', V('golf'))]),
  tip("💡 Mẹo: câu **(+)** thì đuôi **(−)** · câu **(−)** thì đuôi **(+)**. Đuôi dùng **cùng trợ động từ** với câu (is → isn't, play → don't / doesn't, won → didn't)."),
  mistakes([("You are in the team, are you?", "You are in the team, aren't you?", 'Câu (+) → đuôi (−).'), ("She plays golf, don't she?", "She plays golf, doesn't she?", 'She → doesn\'t.'),
            ("They won, weren't they?", "They won, didn't they?", 'won (quá khứ) → didn\'t.'), ("You aren't sore, aren't you?", "You aren't sore, are you?", 'Câu (−) → đuôi (+).')]),
  acts('a3')],
 [Mc('You are in the team, ___ you?', "aren't", 'are', "don't", 'Câu (+) với are → đuôi aren\'t you?', V('team')),
  Mc('She plays golf, ___ she?', "doesn't", "don't", "isn't", 'plays → doesn\'t she?', V('golf')),
  Mc('They won the match, ___ they?', "didn't", "don't", "weren't", 'won (quá khứ) → didn\'t they?', V('match')),
  Mc('He can run fast, ___ he?', "can't", "isn't", "doesn't", 'can → can\'t he?', V('race')),
  Mc('We will win, ___ we?', "won't", "can't", "aren't", 'will → won\'t we?', V('winner')),
  Mc("It isn't a goal, ___ it?", 'is', "isn't", 'does', 'Câu (−) → đuôi (+): is it?', V('goal')),
  Mc("You don't like golf, ___ you?", 'do', "don't", 'are', 'Câu (−) → đuôi (+): do you?', V('golf')),
  Mc("She isn't sore, ___ she?", 'is', "isn't", 'does', 'Câu (−) → đuôi (+): is she?', V('sore')),
  Mc('The winner got a prize, ___ he?', "didn't", "doesn't", "isn't", 'got (quá khứ) → didn\'t he?', V('prize')),
  Mc('Tom and Ben are friends, ___ they?', "aren't", "isn't", "don't", 'are → aren\'t they?'),
  Fl('You like volleyball, ___ you?', "don't", ["don't", "doesn't", "aren't"], 'like → don\'t you?', V('volleyball')),
  Fl('She is a winner, ___ she?', "isn't", ["isn't", "aren't", "doesn't"], 'is → isn\'t she?', V('winner')),
  Fl('They scored a goal, ___ they?', "didn't", ["didn't", "don't", "weren't"], 'scored (quá khứ) → didn\'t they?', V('goal')),
  Fl("You aren't tired, ___ you?", 'are', ['are', "aren't", 'do'], 'Câu (−) → đuôi (+): are you?'),
  Fl('He runs fast, ___ he?', "doesn't", ["doesn't", "don't", "isn't"], 'runs → doesn\'t he?', V('race')),
  Fl("She doesn't play golf, ___ she?", 'does', ['does', "doesn't", 'is'], 'Câu (−) → đuôi (+): does she?', V('golf')),
  Fl('We will win the prize, ___ we?', "won't", ["won't", "can't", "aren't"], 'will → won\'t we?', V('prize')),
  Fl('You can swim, ___ you?', "can't", ["can't", "don't", "aren't"], 'can → can\'t you?'),
  Fl("They didn't lose, ___ they?", 'did', ['did', "didn't", 'were'], 'Câu (−) → đuôi (+): did they?', V('match')),
  Fl('The team is great, ___ it?', "isn't", ["isn't", "aren't", "doesn't"], 'is → isn\'t it?', V('team'))],
 [Dlg(['Tom: You are in the team,'], "Amy: Yes, I am. You are too, ___ you?", "aren't", 'are', "don't", 'Câu (+) → đuôi aren\'t you?', V('team')),
  Dlg(['Boy: He plays volleyball,'], "Girl: Yes, he does. He is good, ___ he?", "isn't", "aren't", "doesn't", 'is → isn\'t he?'),
  Dlg(['Teacher: You don\'t like golf,'], "Pupil: No, I don't. You like it, ___ you?", "don't", 'do', "aren't", 'like → don\'t you?', V('golf')),
  Clz(['The race was very long.', 'Amy came first.'], "She won, ___ she?", "didn't", "doesn't", "wasn't", 'won → didn\'t she?', V('winner')),
  Clz(['Look at the score.', 'It is 3 to 1.'], "We are winning, ___ we?", "aren't", "don't", "isn't", 'are → aren\'t we?', V('score')),
  Clz(['Ben can run very fast.', 'He wins every race.'], "He can win, ___ he?", "can't", "doesn't", "isn't", 'can → can\'t he?', V('race'))])

L4 = lesson('l4', 'rose', '✅', 'Present perfect + already', 'Đã … rồi: have / has + already + V3',
 'Đã xong rồi! Dùng have / has + already + quá khứ phân từ để nói việc đã hoàn thành.',
 [when('🧭 Khi nào dùng?', [
    ('✅', '**have / has + V3** = việc **đã xong** và còn liên quan đến bây giờ.', 'I have won the race.', 'Mình đã thắng cuộc đua rồi.'),
    ('⚡', '**already** = rồi (xong sớm). Đứng **giữa** have / has và V3.', 'She has already scored a goal.', 'Cô ấy đã ghi bàn rồi.'),
    ('👥', '**I / you / we / they + have** · **he / she / it + has**.', 'He has already run ten kilometres.', 'Cậu ấy đã chạy mười cây số rồi.')]),
  compare('🗂 So sánh have và has', [
    CI('have', 'aux', 'I / you / we / they', 'Dùng với **I, you, we, they** và danh từ số nhiều.', [('We have already won.', 'Chúng mình đã thắng rồi.'), ('The players have already left.', 'Các cầu thủ đã đi rồi.')], V('team')),
    CI('has', 'pink', 'he / she / it', 'Dùng với **he, she, it** và danh từ số ít.', [('She has already won.', 'Cô ấy đã thắng rồi.'), ('The team has already scored.', 'Đội đã ghi bàn rồi.')], V('winner'))]),
  table('🗂 Quá khứ phân từ (V3)', ['Nguyên mẫu', 'V3', 'Ví dụ'], [
    ['play (quy tắc)', 'played', 'I have already played.'], ['score (quy tắc)', 'scored', 'She has already scored.'], ['win (bất quy tắc)', 'won', 'We have already won.'],
    ['run (bất quy tắc)', 'run', 'He has already run.'], ['fall (bất quy tắc)', 'fallen', 'She has already fallen over.'], ['eat (bất quy tắc)', 'eaten', 'I have already eaten.']], ['sky', 'mint', 'peach']),
  pattern('1️⃣ Công thức: have / has + already + V3', 'rose', [('subject', 'sub', 'I, she, the team'), ('have / has', 'aux', ''), ('already', 'pink', 'rồi'), ('V3', 'v', 'won, scored'), ('thing', 'obj', 'the race')], [
    ('{I|sub} {have|aux} {already|pink} {won|v} {the race.|obj}', 'Mình đã thắng cuộc đua rồi.', V('winner')),
    ('{She|sub} {has|aux} {already|pink} {scored|v} {a goal.|obj}', 'Cô ấy đã ghi bàn rồi.', V('goal')),
    ('{The team|sub} {has|aux} {already|pink} {won|v} {the prize.|obj}', 'Đội đã nhận giải rồi.', V('prize'))]),
  dialog('❓ Hỏi và trả lời', '{Has|aux} {she|sub} {already|pink} {+ V3?|v}', [
    ('{Has|aux} {she|sub} {already|pink} {scored|v} {a goal?|obj}', '{Yes,|sub} {she has.|aux}', 'Cô ấy đã ghi bàn rồi à?', 'Ừ, cô ấy ghi rồi.', V('goal')),
    ('{Have|aux} {they|sub} {already|pink} {played|v} {the match?|obj}', '{Yes,|sub} {they have.|aux}', 'Họ đã thi đấu trận đó rồi à?', 'Ừ, họ thi đấu rồi.', V('match'))]),
  tip('💡 Mẹo: **have / has + already + V3**. V3 của động từ quy tắc = thêm **-ed** (played). V3 của động từ bất quy tắc phải nhớ (win → won).'),
  mistakes([('She have already won.', 'She has already won.', 'She → has.'), ('I have already win the race.', 'I have already won the race.', 'Dùng V3: won.'),
            ('They have won already the prize.', 'They have already won the prize.', 'already đứng giữa have và V3.'), ('He has already fell over.', 'He has already fallen over.', 'V3 của fall là fallen.')]),
  acts('a4')],
 [Mc('I have already ___ the race.', 'won', 'win', 'winning', 'have + V3: won.', V('race')),
  Mc('She has already ___ a goal.', 'scored', 'score', 'scoring', 'has + V3: scored.', V('goal')),
  Mc('We ___ already finished.', 'have', 'has', 'are', 'We → have finished.'),
  Mc('He has already ___ over.', 'fallen', 'fell', 'fall', 'V3 của fall là fallen.', V('fall-over')),
  Mc('They have already ___ the match.', 'won', 'win', 'wins', 'have + V3: won.', V('match')),
  Mc('My brother ___ already run ten kilometres.', 'has', 'have', 'is', 'My brother → has.'),
  Mc('I have already ___ my lunch.', 'eaten', 'ate', 'eat', 'V3 của eat là eaten.'),
  Mc('The team ___ already scored.', 'has', 'have', 'are', 'The team (số ít) → has.', V('team')),
  Mc('She has ___ finished her race.', 'already', 'ago', 'ever', 'already đứng giữa has và V3.', V('race')),
  Mc('Has the winner ___ got his prize?', 'already', 'ago', 'yesterday', 'Câu hỏi: Has + chủ ngữ + already + V3?', V('prize')),
  Fl('I ___ already won the race.', 'have', ['have', 'has', 'am'], 'I → have + V3.', V('winner')),
  Fl('He ___ already scored a goal.', 'has', ['has', 'have', 'is'], 'He → has + V3.', V('goal')),
  Fl('They have already ___ volleyball. (play)', 'played', ['played', 'play', 'plays'], 'have + V3: played.', V('volleyball')),
  Fl('She has already ___ a race. (run)', 'run', ['run', 'ran', 'running'], 'V3 của run là run.', V('race')),
  Fl('We have ___ finished.', 'already', ['already', 'ago', 'tomorrow'], 'already đứng giữa have và V3.'),
  Fl('The winner has already ___ a prize. (get)', 'got', ['got', 'get', 'getting'], 'has + V3: got.', V('prize')),
  Fl('I have already ___ my lunch. (eat)', 'eaten', ['eaten', 'ate', 'eat'], 'V3 của eat là eaten.'),
  Fl('He has already ___ over. (fall)', 'fallen', ['fallen', 'fell', 'fall'], 'V3 của fall là fallen.', V('fall-over')),
  Fl('The match ___ already started.', 'has', ['has', 'have', 'is'], 'The match (số ít) → has + V3.', V('match')),
  Fl('___ she already scored a goal?', 'Has', ['Has', 'Have', 'Is'], 'She → Has she already…?', V('goal'))],
 [Dlg(['Mum: Is it time for the race?'], 'Tom: No, the race ___ already finished.', 'has', 'have', 'is', 'The race → has already finished.', V('race')),
  Dlg(['Coach: Who won the match?'], 'Girl: Our team has already ___ it!', 'won', 'win', 'winning', 'has + V3: won.', V('match')),
  Dlg(['Boy: Are you hungry?'], 'Girl: No, I ___ already eaten.', 'have', 'has', 'am', 'I → have already eaten.'),
  Clz(['The game is not over.', 'Amy is smiling.'], 'She has already ___ two goals.', 'scored', 'score', 'scoring', 'has + V3: scored.', V('goal')),
  Clz(['Sports day is finished.', 'Everyone is clapping.'], 'The winner has ___ got the prize.', 'already', 'ago', 'ever', 'already đứng giữa has và V3.', V('prize')),
  Clz(['Ben is sitting on the grass.', 'His knee is red.'], 'He has ___ fallen over.', 'already', 'ago', 'tomorrow', 'already đứng giữa has và V3.', V('knee'))])

